<?php
namespace App\Http\Controllers; use App\Models\{MembershipTransaction,Payment}; use Illuminate\Http\Request;
class PaymentController extends Controller { public function index(){return view('payments.index',['payments'=>Payment::with('transaction.member')->latest('paid_at')->paginate(15)]);} public function create(Request $r){return view('payments.form',['payment'=>new Payment(['paid_at'=>now()]),'transactions'=>MembershipTransaction::with('member')->whereIn('status',['Pending','Paid'])->get(),'selected'=>$r->transaction]);} public function store(Request $r){$d=$r->validate(['membership_transaction_id'=>'required|exists:membership_transactions,id','amount'=>'required|numeric|min:0.01','payment_method'=>'required|max:100','paid_at'=>'required|date','notes'=>'nullable']);$t=MembershipTransaction::findOrFail($d['membership_transaction_id']);$already=$t->payments()->sum('amount');if($d['amount']+$already>$t->amount)return back()->withErrors(['amount'=>'Payment exceeds the remaining balance of '.number_format($t->amount-$already,2).'.'])->withInput();$d['receipt_number']='RCP-'.now()->format('Ymd').'-'.str_pad((string)(Payment::count()+1),5,'0',STR_PAD_LEFT);$d['received_by']=auth()->user()->name;Payment::create($d);if($d['amount']+$already >= $t->amount)$t->update(['status'=>'Paid']);return redirect()->route('transactions.show',$t)->with('success','Payment recorded.');} public function show(Payment $payment){$payment->load('transaction.member');return view('payments.show',compact('payment'));} public function receipt(MembershipTransaction $transaction){$transaction->load(['member','level','payments']);return view('payments.receipt',compact('transaction'));} }
